mapper.update:
UPDATE job_screening_configs
SET enabled = #{config.enabled},
    overall_threshold = #{config.overallThreshold},
    dimension_thresholds = CAST(#{config.dimensionThresholds} AS JSONB),
    version = version + 1,
    updated_by = #{config.updatedBy},
    trace_id = #{config.traceId},
    updated_at = #{now}
WHERE job_id = #{config.jobId}
  AND enterprise_id = #{config.enterpriseId}
  AND version = #{expectedVersion}
